const transitionIssue = `-- name: TransitionIssue :one
UPDATE issues
SET state_id = $1, updated_at = NOW()
WHERE id = $2 AND state_id = $3
RETURNING id, project_id, number, title, description, state_id, author_id, created_at, updated_at, deleted_at, deleted_by, priority_id
`

type TransitionIssueParams struct {
	ToState   uuid.UUID
	ID        uuid.UUID
	FromState uuid.UUID
}

// Moves an issue between states, only if it is still in the state the mover
// saw. Two people moving the same card at once both reach this statement; the
// first changes the row and the second matches nothing, so it is told what the
// state became rather than silently overwriting it.
func (q *Queries) TransitionIssue(ctx context.Context, arg TransitionIssueParams) (Issue, error) {
	row := q.db.QueryRow(ctx, transitionIssue, arg.ToState, arg.ID, arg.FromState)
	var i Issue
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.Number,
		&i.Title,
		&i.Description,
		&i.StateID,
		&i.AuthorID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.DeletedBy,
		&i.PriorityID,
	)
	return i, err
}

